    },
  ],
  [
    'malformed report',
    ({ reports }) => {
      reports[0] = [];
    },
  ],
  [
    'failed observer',
    ({ reports }) => {
      reports[0][0].failure = 'Timed out';
    },
  ],
  [
    'unobserved pass',
