});

async function retainedCohort(t, prospective = false) {
  const repository = resolve(dirname(fileURLToPath(import.meta.url)), '..');
  const dir = await realpath(await mkdtemp(join(tmpdir(), 'solo-journal-cost-cohort-')));
  t.after(() => rm(dir, { recursive: true, force: true }));
  const input = prospective
    ? JSON.parse(
        await readFile(join(repository, 'docs/performance/solo-de332-journal-cost-plan.json')),
      )
    : manifest();
  if (prospective) {
    input.release.status = 'reviewed-diagnostic-only';
    for (const key of ['priorProofInspected', 'noUnclosedOwners', 'allPriorPlannedJobsClosed'])
      input.release[key] = true;
    input.release.evidence = [
      {
        runId: 1,
        artifactId: 1,
        artifactSHA256: '0'.repeat(64),
        summarySHA256: '0'.repeat(64),
        disposition: 'failed-reviewed',
      },
    ];
  }
  if (!prospective) input.candidate.inner = { bytes: 1, sha256: '0'.repeat(64) }; // Synthetic test-only package.
  const digest = async (path) => {
    const bytes = await readFile(path);
    return { bytes: bytes.length, sha256: createHash('sha256').update(bytes).digest('hex') };
  };
  for (const ref of [...input.adapterInputs, ...input.frozenTools])
    Object.assign(ref, await digest(join(repository, ref.path)));
  const plan = bindDiagnosticsJob(input, 'chromium'),
    row = { ...plan.rows[0] },
    calls = [];
  const url = 'http://127.0.0.1:9000/game/?journey=opening';
  const closed = {
    status: 'closed',
    exitCode: 0,
    signal: null,
    forcedCleanup: false,
    cleanupUnconfirmed: false,
    violation: null,
    survivors: [],
    ambiguous: [],
  };
  const ctx = {
    plan,
    repository,
    here: join(repository, 'scripts'),
    cleanEnv: {},
    modeState: { recipePath: join(repository, input.recipe.path) },
    report: {},
    inspect: async () => {},
    evidenceSize: async () => 0,
    digest,
    run: async (id, argv, timeout) => {
      calls.push({ id, argv, timeout });
      const stored = JSON.parse(await readFile(join(dir, 'manifest.json')));
      assert.equal(stored.executions.length, 20);
      if (id.endsWith('-timer'))
        await writeFile(
          join(dir, 'timer.json'),
          JSON.stringify({
            status: 'observed',
            address: url,
            crossOriginIsolated: false,
            userAgent: 'unit',
            browser: 'chromium 151',
            minimumPositiveStepMs: 0.001,
            positiveSteps: 100,
          }),
        );
      else {
        assert(timeout > 0 && timeout <= 240000);
        assert(argv.includes('--journal-cost-probe'));
        const data = { environment: { browserVersion: '151' } };
        await writeFile(argv[4], JSON.stringify(data));
      }
      return { ...closed };
    },
  };
  await runDiagnosticsCohort(ctx, row, dir, dir, url, () => 0);
  const stored = JSON.parse(await readFile(join(dir, 'manifest.json'))),
    analysis = JSON.parse(await readFile(join(dir, 'analysis.json')));
  assert.equal(calls.length, 21);
  assert.equal(analysis.observations.length, 20);
  assert.equal(analysis.status, 'unresolved');
  assert.equal(analysis.conditionalStatus, 'unresolved');
  assert.equal(analysis.qualificationAssessment.eligible, false);
  assert.equal(analysis.qualificationAssessment.clockEvidence, 'empirical-minimum-step-only');
  assert.equal(row.status, 'failed');
  assert.equal(row.synchronousJournalHookOverhead, 'unresolved');
  assert.equal(row.appDiagnosticsOverhead, 'not-measured');
  assert.equal(row.hitchJournalOverhead, 'not-measured');
  assert.equal(
    stored.observerSha256,
    plan.frozenTools.find((x) => x.path.endsWith('/qualify-solo-runtime.mjs')).sha256,
  );
  assert.equal(stored.observerLifecycleSha256, undefined);
  assert(stored.journalCostProbeSha256 && stored.hitchJournalSha256);
  assert(stored.executions.every((x) => x.command.status === 'closed' && x.reportSha256));
  assert(
    stored.executions
      .filter((x) => x.diagnostics)
      .every((x) => x.journalReadback.status === 'invalid-evidence'),
  );
  assert(stored.executions.filter((x) => !x.diagnostics).every((x) => !x.journalReadback));
  assert(
    calls
      .slice(1)
      .every(
        (call, index) =>
          call.argv.includes('--hitch-journal') === stored.executions[index].diagnostics,
      ),
  );
  return { stored, analysis };
}
test('new cohort retains all20 owned reports and incomplete journal readback without a false pass', async (t) => {
  const { stored, analysis } = await retainedCohort(t);
  assert.equal(Object.hasOwn(stored, 'analysisMethod'), false);
  assert.equal(Object.hasOwn(analysis, 'analysisMethod'), false);
});
test('prospective journal actual executor records the selected method and retains incomplete binary evidence', async (t) => {
  const { stored, analysis } = await retainedCohort(t, true);
  assert.equal(stored.analysisMethod, 'paired-p95-endpoint-box-v1');
  assert.equal(analysis.analysisMethod, stored.analysisMethod);
  assert.equal(analysis.status, 'unresolved');
  assert.equal(analysis.limit, 0.05);
  assert.equal(analysis.fullJournalOverheadQualification, false);
  assert.equal(analysis.gameplayPerformanceQualification, false);
});

