    if (!child?.pid) return;
    const kill = (kind) => {
      try {
        if (process.platform === 'win32') child.kill(kind);
        else process.kill(-child.pid, kind);
      } catch (error) {
        if (error.code !== 'ESRCH') throw error;
      }
