      ...exit,
      status: timedOut
        ? 'timed-out'
        : interrupted
          ? 'interrupted'
          : spawnError
            ? 'spawn-failed'
            : 'complete',
      spawnError,
    };
  } finally {
    clearTimeout(timeout);
    clearTimeout(killTimeout);
    signal.removeEventListener('abort', cancel);
    await log.close();
